<?php require __DIR__.'/oyunchu_config.php'; $msg='';
function ga_set(string $k,string $v):void{global $conn;$q=$conn->prepare("CREATE TABLE IF NOT EXISTS es_settings(skey VARCHAR(100) PRIMARY KEY,svalue TEXT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");$q->execute();$q=$conn->prepare("INSERT INTO es_settings(skey,svalue) VALUES(?,?) ON DUPLICATE KEY UPDATE svalue=VALUES(svalue)");$q->bind_param('ss',$k,$v);$q->execute();}
function ga_get(string $k,string $d=''):string{global $conn;try{$q=$conn->prepare('SELECT svalue FROM es_settings WHERE skey=?');$q->bind_param('s',$k);$q->execute();$v=$q->get_result()->fetch_column();return ($v===null||$v===false||$v==='')?$d:$v;}catch(Throwable $e){return $d;}}
if($_SERVER['REQUEST_METHOD']==='POST'){ga_verify();$quests=[];foreach(($_POST['qkey']??[]) as $i=>$key){$key=preg_replace('/[^a-zA-Z0-9_-]/','',trim($key));if($key==='')continue;$quests[$key]=['title'=>trim($_POST['qtitle'][$i]??''),'metric'=>trim($_POST['qmetric'][$i]??'games_played'),'target'=>max(1,(int)($_POST['qtarget'][$i]??1)),'reward'=>max(0,(int)($_POST['qreward'][$i]??0))];}ga_set('oh_quest_definitions',json_encode($quests,JSON_UNESCAPED_UNICODE));$daily=[];for($i=0;$i<7;$i++)$daily[]=max(0,(int)($_POST['daily'][$i]??0));ga_set('oh_daily_login_rewards',implode(',',$daily));ga_set('oh_referral_reward',(string)max(0,(int)($_POST['referral_reward']??20)));ga_set('oh_ad_reward_coins',(string)max(0,(int)($_POST['ad_reward_coins']??5)));ga_set('oh_daily_free_attempts',(string)max(1,(int)($_POST['daily_free_attempts']??5)));ga_set('oh_extra_attempt_cost_1',(string)max(0,(int)($_POST['extra_attempt_cost_1']??60)));ga_set('oh_extra_attempt_cost_2',(string)max(0,(int)($_POST['extra_attempt_cost_2']??250)));ga_set('oh_extra_attempt_cost_3',(string)max(0,(int)($_POST['extra_attempt_cost_3']??350)));ga_set('oh_extra_attempt_cost_4',(string)max(0,(int)($_POST['extra_attempt_cost_4']??1000)));ga_audit('oyunchu_settings','es_settings',null,'Oyunçu iqtisadiyyat/quest ayarları');$msg='Ayarlar yadda saxlanıldı.';}
$qraw=ga_get('oh_quest_definitions','');$quests=$qraw?json_decode($qraw,true):null;if(!is_array($quests)||!$quests)$quests=['play_1'=>['title'=>'Bugün 1 tur oyna','metric'=>'games_played','target'=>1,'reward'=>10], 'play_2_games'=>['title'=>'Bugün 2 fərqli oyun sına','metric'=>'distinct_games','target'=>2,'reward'=>15], 'earn_15_coins'=>['title'=>'Bugün 15 coin qazan','metric'=>'coins_earned','target'=>15,'reward'=>10]];$daily=array_map('intval',array_pad(array_filter(array_map('intval',explode(',',ga_get('oh_daily_login_rewards','5,8,10,12,15,18,30'))),fn($v)=>$v>=0),7,0));$ref=(int)ga_get('oh_referral_reward','20');$ad=(int)ga_get('oh_ad_reward_coins','5');$dailyFree=(int)ga_get('oh_daily_free_attempts','5');$cost1=(int)ga_get('oh_extra_attempt_cost_1','60');$cost2=(int)ga_get('oh_extra_attempt_cost_2','250');$cost3=(int)ga_get('oh_extra_attempt_cost_3','350');$cost4=(int)ga_get('oh_extra_attempt_cost_4','1000');
?><!doctype html><html lang="az" data-theme="dark"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Oyunçu Ayarları</title><script>document.documentElement.setAttribute('data-theme',localStorage.getItem('esevgili_theme')||'dark');</script></head><body><?php include __DIR__.'/oyunchu_sidebar.php';?><main class="ga-main"><div class="ga-top"><b>⚙️ Oyunçu iqtisadiyyat və Quest ayarları</b></div><div class="ga-content"><?php if($msg):?><div class="ga-alert"><?=$msg?></div><?php endif;?><form method="post"><?=csrf_field()?><div class="ga-card"><h3>Gündəlik Login — 7 günlük mükafat</h3><div class="ga-grid"><?php for($i=0;$i<7;$i++):?><div><label class="ga-label">Gün <?=$i+1?></label><input class="ga-input" type="number" min="0" name="daily[]" value="<?=ga_h($daily[$i]??0)?>"></div><?php endfor;?></div></div><br><div class="ga-card"><h3>🎯 Bütün oyunlar — gündəlik cəhd sistemi</h3><p class="ga-muted">Bütün oyunlarda gündəlik pulsuz cəhd sayı və 5 pulsuz cəhddən sonrakı coin qiymətləri burada mərkəzləşdirilir.</p><div class="ga-grid"><div><label class="ga-label">Gündəlik pulsuz cəhd</label><input class="ga-input" type="number" min="1" name="daily_free_attempts" value="<?=$dailyFree?>"></div><div><label class="ga-label">6-cı cəhd — coin</label><input class="ga-input" type="number" min="0" name="extra_attempt_cost_1" value="<?=$cost1?>"></div><div><label class="ga-label">7-ci cəhd — coin</label><input class="ga-input" type="number" min="0" name="extra_attempt_cost_2" value="<?=$cost2?>"></div><div><label class="ga-label">8-ci cəhd — coin</label><input class="ga-input" type="number" min="0" name="extra_attempt_cost_3" value="<?=$cost3?>"></div><div><label class="ga-label">9-cu və sonrakı — coin</label><input class="ga-input" type="number" min="0" name="extra_attempt_cost_4" value="<?=$cost4?>"></div></div></div><br><div class="ga-card"><h3>Digər mükafatlar</h3><div class="ga-form"><div><label class="ga-label">Referral mükafatı</label><input class="ga-input" type="number" min="0" name="referral_reward" value="<?=$ref?>"></div><div><label class="ga-label">Reklam baxış coin</label><input class="ga-input" type="number" min="0" name="ad_reward_coins" value="<?=$ad?>"></div></div></div><br><div class="ga-card"><h3>Gündəlik Quest-lər</h3><table class="ga-table" id="questTable"><tr><th>Key</th><th>Başlıq</th><th>Metric</th><th>Hədəf</th><th>Reward</th><th></th></tr><?php foreach($quests as $k=>$v):?><tr><td><input class="ga-input" name="qkey[]" value="<?=ga_h($k)?>"></td><td><input class="ga-input" name="qtitle[]" value="<?=ga_h($v['title'])?>"></td><td><input class="ga-input" name="qmetric[]" value="<?=ga_h($v['metric'])?>"></td><td><input class="ga-input" type="number" name="qtarget[]" value="<?=ga_h($v['target'])?>"></td><td><input class="ga-input" type="number" name="qreward[]" value="<?=ga_h($v['reward'])?>"></td><td><button type="button" class="ga-btn ga-danger" onclick="this.closest('tr').remove()">Sil</button></td></tr><?php endforeach;?></table><button type="button" class="ga-btn ga-mutedbtn" onclick="addQuest()">+ Quest əlavə et</button><p class="ga-muted">Metric: games_played, distinct_games və ya coins_earned.</p></div><br><button class="ga-btn ga-primary">Bütün ayarları yadda saxla</button></form></div></main><script>function addQuest(){const t=document.getElementById('questTable');const r=t.insertRow(-1);r.innerHTML='<td><input class="ga-input" name="qkey[]"></td><td><input class="ga-input" name="qtitle[]"></td><td><select class="ga-input" name="qmetric[]"><option>games_played</option><option>distinct_games</option><option>coins_earned</option></select></td><td><input class="ga-input" type="number" min="1" name="qtarget[]" value="1"></td><td><input class="ga-input" type="number" min="0" name="qreward[]" value="10"></td><td><button type="button" class="ga-btn ga-danger" onclick="this.closest('tr').remove()">Sil</button></td>';}</script></body></html>
